package com.example.blades360;

import android.content.*;
import android.graphics.*;
import android.view.*;
import org.json.*;
import java.util.*;

/** Games blade achievement list and per-game achievement details. */
final class RetroMarketplace extends View {
  final MainActivity a;final RetroAchievements ra;final Paint p=new Paint(3);final ArrayList<Item> rows=new ArrayList<>();
  int screen,index,offset;float scale=1,left,height=720,down;long stick;String heading="RetroAchievements";JSONObject detail;boolean closed;
  static class Item{String title,sub,body,image;Runnable run;Item(String t,String s,String b,String i,Runnable r){title=t;sub=s;body=b;image=i;run=r;}}
  RetroMarketplace(MainActivity a){super(a);this.a=a;ra=a.retroAchievements;setFocusableInTouchMode(true);ra.changed=()->{int selected=index,scroll=offset;build();index=Math.min(selected,Math.max(0,rows.size()-1));offset=scroll;invalidate();};home();}
  void add(String title,String sub,String body,String image,Runnable run){rows.add(new Item(title,sub,body,image,run));}
  void home(){screen=2;index=offset=0;build();invalidate();}
  void page(int n){screen=n;index=offset=0;build();invalidate();}
  void build(){rows.clear();if(screen==0){heading="RetroAchievements";
    add("My Gamer Profile",ra.hasData()?ra.profile.optString("User"):"Connect your account",summary(),ra.profile.optString("UserPic"),()->page(1));
    add("My Games","Achievement progress",ra.games.length()+" games on your RetroAchievements profile. Browse sets, earned badges and remaining challenges.","",()->page(2));
    add("Completed Games","Your completed achievement sets","Games where all achievements have been unlocked. Hardcore completion is shown separately.","",()->page(3));
    add("Refresh Profile",ra.busy?"Syncing…":"Download latest progress",ra.status,"",ra::refresh);
    add("Account Connection",ra.username().isEmpty()?"Not connected":ra.username(),"Connect using your RetroAchievements username and Web API key. Your password is not required.","",()->page(4));
  }else if(screen==1){heading="My Gamer Profile";add(ra.profile.optString("User","No account data"),"Player profile",summary(),ra.profile.optString("UserPic"),()->{});add("Hardcore Points",ra.hasData()?""+ra.profile.optLong("TotalPoints"):"—","Points earned in Hardcore mode.","",()->{});add("Softcore Points",ra.hasData()?""+ra.profile.optLong("TotalSoftcorePoints"):"—","Points earned with Hardcore disabled.","",()->{});add("Achievements Unlocked",ra.achievements(),"Unique unlocks across all loaded game sets. Hardcore unlocks are included once.","",()->{});add("Refresh Profile","",ra.status,"",ra::refresh);
  }else if(screen==2||screen==3){heading=screen==2?"Achievements":"Completed Games";ArrayList<JSONObject> games=new ArrayList<>();for(int i=0;i<ra.games.length();i++){JSONObject g=ra.games.optJSONObject(i);if(g!=null&&(screen==2||g.optInt("MaxPossible")>0&&g.optInt("NumAwarded")>=g.optInt("MaxPossible")))games.add(g);}games.sort(Comparator.comparing(g->g.optString("Title"),String.CASE_INSENSITIVE_ORDER));for(JSONObject g:games){add(g.optString("Title"),g.optInt("NumAwarded")+" / "+g.optInt("MaxPossible")+" achievements · "+g.optString("ConsoleName"),g.optInt("NumAwarded")+" / "+g.optInt("MaxPossible")+" achievements unlocked\n"+g.optInt("NumAwardedHardcore")+" in Hardcore\n\nSelect to view the achievement set.",g.optString("ImageIcon"),()->loadGame(g.optInt("GameID")));}if(rows.isEmpty())add(ra.hasData()?"No games to show":"Connect and refresh your profile","",ra.status,"",()->page(4));
  }else if(screen==4){heading="Account Connection";add("Username",ra.username().isEmpty()?"Not set":ra.username(),"Enter your RetroAchievements username. This is independent of your local Blades gamertag.","",this::username);
    add("Web API Key",ra.prefs.contains("key")?"Saved securely":"Not set","Find your Web API key in your RetroAchievements account settings. Enter the key here, not your password.","",this::enterKey);
    add("Paste Web API Key","From this device's clipboard","Copies the key only when selected. The saved key is encrypted using Android Keystore.","",this::pasteKey);
    add("Connect / Refresh","",ra.status,"",ra::refresh);
    add("Dashboard score: "+ra.scoreMode(),"Select to change","Combined includes Hardcore and Softcore points. Achievements always shows unique unlocks.","",()->{ra.prefs.edit().putInt("score_mode",(ra.prefs.getInt("score_mode",0)+1)%3).apply();ra.notifyChanged();});
    add("Disconnect Account","Remove key and saved stats","Your RetroAchievements account and remote progress are not changed.","",()->page(6));
  }else if(screen==5&&detail!=null){heading=detail.optString("Title","Achievements");JSONObject set=detail.optJSONObject("Achievements");ArrayList<JSONObject> list=new ArrayList<>();if(set!=null){Iterator<String> keys=set.keys();while(keys.hasNext()){JSONObject item=set.optJSONObject(keys.next());if(item!=null)list.add(item);}}list.sort(Comparator.comparingInt(g->g.optInt("DisplayOrder")));for(JSONObject g:list){boolean hard=!g.optString("DateEarnedHardcore","").isEmpty()&&!g.isNull("DateEarnedHardcore"),earned=hard||!g.optString("DateEarned","").isEmpty()&&!g.isNull("DateEarned");String badge=g.optString("BadgeName");add(g.optString("Title"),g.optInt("Points")+" points • "+(hard?"Hardcore":earned?"Unlocked":"Locked"),g.optString("Description")+(earned?"\n\nUnlocked: "+g.optString(hard?"DateEarnedHardcore":"DateEarned"):""),badge.matches("[0-9]+")?"/Badge/"+badge+(earned?"":"_lock")+".png":"",()->{});}if(rows.isEmpty())add("No achievements in this set","","No achievements were returned by RetroAchievements.","",()->{});
  }else if(screen==6){heading="Disconnect Account?";add("Cancel","","Keep your connection and saved data.","",()->page(4));add("Disconnect","","Remove this app's key and cached profile.","",()->{ra.disconnect();page(4);});}}
  String summary(){return ra.hasData()?ra.profile.optString("User")+"\n\n"+ra.score()+" points ("+ra.scoreMode()+")\n"+ra.achievements()+" achievements\n"+ra.games.length()+" games\n\n"+ra.profile.optString("Motto",""):"Connect your RetroAchievements account to view points, achievements and game progress here. Your local game library stays unchanged.";}
  void loadGame(int id){int origin=screen;ra.game(id,g->{if(!closed&&screen==origin){detail=g;page(5);}});}
  void username(){a.tools.editor=new BladesKeyboard(a,"RetroAchievements Username",ra.username(),64,false,s->{ra.setUsername(s);page(4);requestFocus();},()->{a.tools.editor=null;post(this::requestFocus);});}
  void enterKey(){boolean secure=(a.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0;a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);a.tools.editor=new BladesKeyboard(a,"RetroAchievements Web API Key","",128,false,s->{ra.setKey(s);page(4);requestFocus();},()->{a.tools.editor=null;if(!secure)a.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);post(this::requestFocus);});a.tools.editor.secret=true;}
  void pasteKey(){android.content.ClipboardManager clipboard=(android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE);ClipData clip=clipboard.getPrimaryClip();if(clip==null||clip.getItemCount()==0){ra.status="Clipboard is empty";invalidate();return;}CharSequence text=clip.getItemAt(0).getText();if(text==null){ra.status="Clipboard does not contain a key";invalidate();return;}ra.setKey(text.toString());}
  void back(){if(screen==2)close();else if(screen==5)page(2);else if(screen==6)page(4);else home();}
  void close(){closed=true;ra.changed=()->{};if(getParent() instanceof ViewGroup)((ViewGroup)getParent()).removeView(this);a.marketplace=null;a.dashboard.requestFocus();}
  int slots(){return Math.max(3,Math.min(9,(int)((height-300)/61)));}
  void move(int n){index=Math.max(0,Math.min(rows.size()-1,index+n));if(index<offset)offset=index;if(index>=offset+slots())offset=index-slots()+1;invalidate();}
  void select(){if(index>=0&&index<rows.size())rows.get(index).run.run();invalidate();}
  @Override public boolean onKeyDown(int key,KeyEvent e){if(e.getRepeatCount()>0&&(key==96||key==97))return true;switch(key){case 19:move(-1);break;case 20:move(1);break;case 102:move(-slots());break;case 103:move(slots());break;case 96:case 66:case 23:select();break;case 97:case 4:back();break;case 99:page(0);break;case 100:ra.refresh();break;}return true;}
  @Override public boolean onKeyUp(int key,KeyEvent e){return true;}
  @Override public boolean onGenericMotionEvent(MotionEvent e){float y=e.getAxisValue(16);if(Math.abs(y)<.5f)y=e.getAxisValue(1);long now=android.os.SystemClock.uptimeMillis();if(Math.abs(y)<.5f){stick=0;return true;}if(now-stick>180){move(y>0?1:-1);stick=now;}return true;}
  void text(Canvas c,String s,float x,float y,float size,int color){p.setShader(null);p.setColor(color);p.setTypeface(a.dashboard.regular);p.setTextSize(size);c.drawText(s,x,y,p);}
  String fit(String s,float width,float size){p.setTypeface(a.dashboard.regular);p.setTextSize(size);if(p.measureText(s)<=width)return s;int n=s.length();while(n>0&&p.measureText(s.substring(0,n)+"…")>width)n--;return s.substring(0,n)+"…";}
  void gradient(Canvas c,RectF r,int top,int bottom,float radius){p.setShader(new LinearGradient(r.left,r.top,r.left,r.bottom,top,bottom,Shader.TileMode.CLAMP));c.drawRoundRect(r,radius,radius,p);p.setShader(null);}
  void button(Canvas c,float x,float y,String letter,String label,int color){p.setShader(new RadialGradient(x-4,y-5,17,new int[]{0xfff5f7de,color,0xff60543b},null,Shader.TileMode.CLAMP));c.drawCircle(x,y,15,p);p.setShader(null);text(c,letter,x-8,y+8,23,Color.WHITE);text(c,label,x+24,y+8,24,0xfffff9e9);}
  void wrapped(Canvas c,String s,float x,float y,float width,float size,float bottom){for(String paragraph:s.split("\n",-1)){String line="";for(String word:paragraph.split(" ")){p.setTextSize(size);if(p.measureText(line+" "+word)>width&&!line.isEmpty()){if(y>bottom)return;text(c,line,x,y,size,0xff3a3025);y+=size+6;line=word;}else line=line.isEmpty()?word:line+" "+word;}if(y>bottom)return;text(c,line,x,y,size,0xff3a3025);y+=size+6;}}
  @Override protected void onDraw(Canvas c){scale=Math.min(getWidth()/1280f,getHeight()/720f);height=getHeight()/scale;left=(getWidth()-1280*scale)/2;c.drawColor(0xff314925);c.save();c.translate(left,0);c.scale(scale,scale);
    gradient(c,new RectF(70,0,1220,height),0xff749846,0xffdce6bd,0);
    Path edge=new Path();edge.moveTo(0,0);edge.lineTo(101,0);edge.cubicTo(106,80,103,102,81,117);edge.cubicTo(61,132,72,height*.66f,82,height*.73f);edge.cubicTo(97,height*.86f,105,height*.94f,100,height);edge.lineTo(0,height);edge.close();p.setShader(new LinearGradient(0,0,105,0,new int[]{0xff264a26,0xff72a333,0xffc2d58e,0xff335523},null,Shader.TileMode.CLAMP));c.drawPath(edge,p);p.setShader(null);
    c.save();c.translate(43,140);c.rotate(90);text(c,"games",0,0,26,0xff263623);c.restore();
    gradient(c,new RectF(102,-20,1200,96),0xff213f21,0xff4c702e,25);text(c,"Achievements",132,60,38,Color.WHITE);text(c,fit(ra.username(),300,24),850,58,24,0xffecf0d6);
    text(c,fit(heading,1000,30),135,145,30,0xff24391f);text(c,ra.score()+" G   •   "+ra.achievements()+" Achievements",135,181,23,0xff415434);
    for(int i=offset;i<Math.min(rows.size(),offset+slots());i++){float y=215+(i-offset)*61;Item item=rows.get(i);if(i==index)gradient(c,new RectF(123,y-2,760,y+56),0xfff6f8d9,0xffb3ce7c,8);Bitmap icon=ra.image(item.image);if(icon!=null){p.setColor(Color.WHITE);c.drawBitmap(icon,null,new RectF(139,y+4,185,y+50),p);}text(c,fit(item.title,535,25),200,y+25,25,0xff263922);text(c,fit(item.sub,535,18),200,y+48,18,0xff4c5f3a);p.setColor(0x55556942);c.drawLine(135,y+59,752,y+59,p);}
    if(offset>0)text(c,"▲",730,205,20,0xff476133);if(offset+slots()<rows.size())text(c,"▼",730,220+slots()*61,20,0xff476133);
    if(!rows.isEmpty()){Item item=rows.get(Math.min(index,rows.size()-1));float bodyY=250;Bitmap art=ra.image(item.image);if(art!=null){float h=145,w=h*art.getWidth()/art.getHeight();if(w>280){w=280;h=w*art.getHeight()/art.getWidth();}p.setColor(Color.WHITE);c.drawBitmap(art,null,new RectF(815,225,815+w,225+h),p);bodyY=260+h;}wrapped(c,item.body,800,bodyY,345,23,height-145);}
    gradient(c,new RectF(102,height-104,1200,height+20),0xff9dbb6c,0xffd4e2ae,20);button(c,150,height-45,"A","Select",0xff7eaf3c);button(c,330,height-45,"B","Back",0xffbb4436);button(c,490,height-45,"Y","Refresh",0xffd2b747);button(c,710,height-45,"X","Options",0xff368dc2);text(c,fit(ra.status,1000,18),135,height-78,18,0xff33482b);c.restore();}
  @Override public boolean onTouchEvent(MotionEvent e){float x=(e.getX()-left)/scale,y=e.getY()/scale;if(e.getAction()==0){down=y;return true;}if(e.getAction()!=1)return true;if(Math.abs(y-down)>45){move(y<down?slots():-slots());return true;}if(y>height-65){if(x<290)select();else if(x<440)back();else if(x<680)ra.refresh();else page(0);return true;}if(x<110){back();return true;}if(x<760&&y>=215){int n=offset+(int)((y-215)/61);if(n<rows.size()&&n<offset+slots()){if(n==index)select();else{index=n;invalidate();}}}return true;}
}
